/* From Uiverse.io by wojtek221221 - Source: wojtek221 - Tags: stats, cookies, cookie card, simple cards, Alerts, card design */
.__UIV_SCOPE__ .cookie-card {
  border-radius: 15px;
  width: 320px;
  height: 200px;
  background-color: #fff;
}

.__UIV_SCOPE__ .cookie-title {
  font-size: 20px;
  position: relative;
  left: 90px;
  top: 15px;
  font-weight: bold;
  color: rgb(31 41 55);
}

.__UIV_SCOPE__ .cookie-description {
  position: relative;
  top: 25px;
  font-size: 15px;
  text-align: center;
  font-family: Verdana, Geneva, Tahoma, sans-serif;
  color: rgb(75 85 99);
}

.__UIV_SCOPE__ .cookies-policy {
  color: rgb(31 41 55);
  text-decoration: underline;
}

.__UIV_SCOPE__ .cookies-policy:hover {
  text-decoration: none;
}

.__UIV_SCOPE__ .cookies-policy:active {
  color: rgba(31, 41, 55, 0.61);
  ;
}

.__UIV_SCOPE__ .accept-button {
  cursor: pointer;
  font-weight: bold;
  border-radius: 5px;
  width: 85px;
  height: 35px;
  background-color: rgba(255, 255, 255, 0);
  position: relative;
  left: 115px;
  top: 45px;
}

.__UIV_SCOPE__ .accept-button:hover {
  background-color: rgb(31 41 55);
  color: #fff;
  border: rgb(31 41 55);
  ;
}

.__UIV_SCOPE__ .accept-button:active {
  font-weight: 100;
}
